<template><el-card shadow="hover"><template #header><div class="header"><span>厅任务流水数据</span><div><span class="summary">最近成功同步时间：{{summary.finishedAt||'-'}}</span><el-button type="warning" :loading="syncing" @click="runSync">同步厅数据</el-button></div></div></template>
	<el-table v-loading="table.loading" :data="table.list" border stripe><el-table-column prop="startDate" label="开始日期" width="110"/><el-table-column prop="endDate" label="结束日期" width="110"/><el-table-column prop="hallName" label="厅名" min-width="140"/><el-table-column prop="hallId" label="厅号" width="90"/><el-table-column prop="roomId" label="roomId" width="115"/><el-table-column prop="rank" label="排名" width="75"/><el-table-column prop="effectiveAnchorNum" label="有效主播" width="95"/><el-table-column prop="effectiveNum" label="有效个播" width="95"/><el-table-column prop="effectiveOpenDayNum" label="有效开播天数" width="115"/><el-table-column prop="openLiveTimeText" label="开播时长" width="120"/><el-table-column prop="totalFlow" label="总流水" width="110"/><el-table-column prop="luckyBagFlow" label="福袋流水" width="110"/><el-table-column prop="crossPkNum" label="跨厅PK" width="85"/><el-table-column prop="roomPkNum" label="同房PK" width="85"/></el-table><pagination v-show="table.total>0" v-model:page="table.pageNum" v-model:limit="table.pageSize" :total="table.total" @pagination="load"/></el-card></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{getFlowDataSummary,getFlowDataTasks,syncFlowData}from'/@/api/system/flowData';defineOptions({name:'flowDataTasks'});const syncing=ref(false);const summary=reactive({finishedAt:''});const table=reactive({list:[]as any[],total:0,pageNum:1,pageSize:20,loading:false});const load=async()=>{table.loading=true;try{const r:any=await getFlowDataTasks({pageNum:table.pageNum,pageSize:table.pageSize});table.list=r.data.list??[];table.total=r.data.total??0;}finally{table.loading=false;}};const loadSummary=async()=>Object.assign(summary,(await getFlowDataSummary()as any).data);const runSync=async()=>{await ElMessageBox.confirm('确认同步厅数据？','同步确认',{type:'warning'});syncing.value=true;try{const r:any=await syncFlowData();ElMessage.success(`同步成功：新增 ${r.data.insertedCount}，更新 ${r.data.updatedCount}`);await Promise.all([load(),loadSummary()]);}finally{syncing.value=false;}};onMounted(()=>Promise.allSettled([load(),loadSummary()]));</script>
<style scoped>.header{display:flex;justify-content:space-between;align-items:center}.summary{margin-right:16px;color:var(--el-text-color-secondary)}</style>
